insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('7b1046ea-aebe-49d0-b8a2-56d3bfffba26', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', null, 'topic'::public.curated_course_node_type, 'Statistical thinking for kinesiology and health sciences', 'Statistics helps kinesiology students move from anecdotes to evidence. This section frames statistics as a decision tool for research, clinical reasoning, coaching, performance, and public health.', 0),
  ('f4e74a3e-aaf3-404f-8b38-85d0a8e86b98', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '7b1046ea-aebe-49d0-b8a2-56d3bfffba26', 'subtopic'::public.curated_course_node_type, 'Evidence, uncertainty, and decision-making', 'Students learn why data never speaks alone; it must be interpreted with uncertainty, context, and professional judgment.', 0),
  ('859c7018-e904-4885-86dd-e44156470e1d', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'f4e74a3e-aaf3-404f-8b38-85d0a8e86b98', 'concept'::public.curated_course_node_type, 'Population versus sample reasoning', null, 0),
  ('1fc1ceae-bf1f-421f-b0b1-3ee13c1ae149', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'f4e74a3e-aaf3-404f-8b38-85d0a8e86b98', 'concept'::public.curated_course_node_type, 'Association, prediction, causation, and decision support', null, 1),
  ('2b01d183-b6a2-4a30-ab36-509979baa34a', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'f4e74a3e-aaf3-404f-8b38-85d0a8e86b98', 'concept'::public.curated_course_node_type, 'Statistical versus practical questions', null, 2),
  ('ab554a4f-ca5c-4fff-bfee-b2ca9e7d4bf3', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'f4e74a3e-aaf3-404f-8b38-85d0a8e86b98', 'concept'::public.curated_course_node_type, 'Examples from exercise testing, injury prevention, rehabilitation, and sport science', null, 3),
  ('e2a2b88d-e862-4e1e-9676-46cbfd58e4cf', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '7b1046ea-aebe-49d0-b8a2-56d3bfffba26', 'subtopic'::public.curated_course_node_type, 'Research questions and statistical claims', 'The point is to match the statistical method to the question being asked.', 1),
  ('1e3ddc29-5580-479a-adfd-0c4354949c2b', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'e2a2b88d-e862-4e1e-9676-46cbfd58e4cf', 'concept'::public.curated_course_node_type, 'Describing groups, estimating effects, comparing interventions, and modeling relationships', null, 0),
  ('c2a0eae8-2f5c-41ab-a029-07b917e1e7a7', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'e2a2b88d-e862-4e1e-9676-46cbfd58e4cf', 'concept'::public.curated_course_node_type, 'Outcome, exposure, predictor, response, and covariate language', null, 1),
  ('85b3d034-8af3-4e3d-8984-cbae1f687d13', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'e2a2b88d-e862-4e1e-9676-46cbfd58e4cf', 'concept'::public.curated_course_node_type, 'Operational definitions and measurement choices', null, 2),
  ('74c15b84-48de-48b1-b206-bd63cce07e8b', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'e2a2b88d-e862-4e1e-9676-46cbfd58e4cf', 'concept'::public.curated_course_node_type, 'Common statistical claims in kinesiology literature', null, 3),
  ('5bb77e5d-921c-49f5-b732-50990c355a9e', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', null, 'topic'::public.curated_course_node_type, 'Data types, data quality, visualization, and descriptive statistics', 'Before inference comes description. This section teaches students to understand what kind of data they have, whether it is trustworthy, and how to summarize it clearly.', 1),
  ('38303169-3dd1-4bfb-94a6-71d270fd9397', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '5bb77e5d-921c-49f5-b732-50990c355a9e', 'subtopic'::public.curated_course_node_type, 'Variables, data quality, and visualization', 'Students learn to inspect datasets before calculating or testing anything.', 0),
  ('d5fbd662-a8ad-489b-a667-e3c60d27b190', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '38303169-3dd1-4bfb-94a6-71d270fd9397', 'concept'::public.curated_course_node_type, 'Categorical, ordinal, interval, ratio, count, and time-to-event variables', null, 0),
  ('c7829d69-a143-4572-b084-d2d9c2209f7d', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '38303169-3dd1-4bfb-94a6-71d270fd9397', 'concept'::public.curated_course_node_type, 'Missing data, impossible values, outliers, duplicates, and coding errors', null, 1),
  ('9c96cc9d-d825-4a2e-8b3b-f7993dce5a88', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '38303169-3dd1-4bfb-94a6-71d270fd9397', 'concept'::public.curated_course_node_type, 'Histograms, boxplots, scatterplots, bar charts, and line plots', null, 2),
  ('5ef7f81d-1a17-4b35-8eca-232c1e9c0c87', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '38303169-3dd1-4bfb-94a6-71d270fd9397', 'concept'::public.curated_course_node_type, 'Misleading graphs and ethical visualization choices', null, 3),
  ('bcb71fa4-177a-4519-99e9-a645eb4e709c', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '5bb77e5d-921c-49f5-b732-50990c355a9e', 'subtopic'::public.curated_course_node_type, 'Descriptive summaries', 'The gist is to summarize data in ways that match the variable and distribution.', 1),
  ('c3e75dda-8f0c-4e7e-bb6a-369aee4ffa93', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'bcb71fa4-177a-4519-99e9-a645eb4e709c', 'concept'::public.curated_course_node_type, 'Mean, median, mode, percentiles, and proportions', null, 0),
  ('971930b7-6dfe-41e3-88e8-ba044098ed66', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'bcb71fa4-177a-4519-99e9-a645eb4e709c', 'concept'::public.curated_course_node_type, 'Range, interquartile range, variance, standard deviation, and coefficient of variation', null, 1),
  ('10a60eb8-1c72-424b-bf97-e8d2d0422205', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'bcb71fa4-177a-4519-99e9-a645eb4e709c', 'concept'::public.curated_course_node_type, 'Skewness, distribution shape, floor/ceiling effects, and transformations', null, 2),
  ('2039587b-cd01-40ae-bc94-c4b29dce1f70', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'bcb71fa4-177a-4519-99e9-a645eb4e709c', 'concept'::public.curated_course_node_type, 'Reporting descriptive results for health and performance data', null, 3),
  ('03433f75-b907-4ac0-b7af-0ff8987051c5', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', null, 'topic'::public.curated_course_node_type, 'Probability, uncertainty, and diagnostic reasoning', 'Probability gives students a language for uncertainty. In kinesiology and health sciences, it supports risk interpretation, screening decisions, and evidence-based judgment.', 2),
  ('e86023b6-f615-403b-bd8f-453b453f248d', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '03433f75-b907-4ac0-b7af-0ff8987051c5', 'subtopic'::public.curated_course_node_type, 'Core probability concepts', 'Students learn the rules behind risk, chance, and conditional statements.', 0),
  ('ccf46e67-4f30-461d-8b29-d46ad4e44f18', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'e86023b6-f615-403b-bd8f-453b453f248d', 'concept'::public.curated_course_node_type, 'Events, complements, unions, intersections, and independence', null, 0),
  ('f8369baf-d208-4b13-9603-28ee77289e9a', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'e86023b6-f615-403b-bd8f-453b453f248d', 'concept'::public.curated_course_node_type, 'Conditional probability and Bayes-style reasoning', null, 1),
  ('d5f99538-d0fa-4cb4-bbdc-fdc6ff080b42', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'e86023b6-f615-403b-bd8f-453b453f248d', 'concept'::public.curated_course_node_type, 'Expected value and variability', null, 2),
  ('d1240b3f-977f-4f14-a256-4a194fb04e90', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'e86023b6-f615-403b-bd8f-453b453f248d', 'concept'::public.curated_course_node_type, 'Probability statements in sport, health, and rehabilitation contexts', null, 3),
  ('c4aa9055-7bb5-4fd1-b0fd-f5daed578b96', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '03433f75-b907-4ac0-b7af-0ff8987051c5', 'subtopic'::public.curated_course_node_type, 'Screening and diagnostic reasoning', 'The point is to understand how test accuracy and prevalence affect interpretation.', 1),
  ('1f0d576c-cd56-47cc-8906-99c3895912ad', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'c4aa9055-7bb5-4fd1-b0fd-f5daed578b96', 'concept'::public.curated_course_node_type, 'Sensitivity, specificity, false positives, and false negatives', null, 0),
  ('c372c71f-9945-4c96-adc3-af482f278e7c', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'c4aa9055-7bb5-4fd1-b0fd-f5daed578b96', 'concept'::public.curated_course_node_type, 'Positive and negative predictive value', null, 1),
  ('bfc146b5-d0a7-492d-addf-6b89e2ac2f86', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'c4aa9055-7bb5-4fd1-b0fd-f5daed578b96', 'concept'::public.curated_course_node_type, 'Likelihood ratios and pretest probability intuition', null, 2),
  ('c227616c-1467-48bd-8ac2-09cb16c6238d', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'c4aa9055-7bb5-4fd1-b0fd-f5daed578b96', 'concept'::public.curated_course_node_type, 'Screening examples from fitness testing, concussion, injury risk, and health appraisal', null, 3),
  ('86057e08-38e8-4c09-bc57-bfb24a792115', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', null, 'topic'::public.curated_course_node_type, 'Distributions, standard scores, and sampling variability', 'Distributions connect raw scores to probabilities and inference. This section builds the foundation for confidence intervals, hypothesis tests, and model assumptions.', 3),
  ('07c4229c-36af-4684-b5f2-fd4aa3c88b5d', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '86057e08-38e8-4c09-bc57-bfb24a792115', 'subtopic'::public.curated_course_node_type, 'Common distributions and standard scores', 'Students learn why different statistical methods rely on different reference distributions.', 0),
  ('4355ac28-787c-447c-bd2b-4ca92817d71c', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '07c4229c-36af-4684-b5f2-fd4aa3c88b5d', 'concept'::public.curated_course_node_type, 'Normal, t, chi-square, F, and binomial distributions', null, 0),
  ('0f26be03-9d7f-45fb-9490-683b3b95e9a9', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '07c4229c-36af-4684-b5f2-fd4aa3c88b5d', 'concept'::public.curated_course_node_type, 'z-scores, percentiles, and standardized comparisons', null, 1),
  ('338c5d87-4607-4f7c-9561-59e73f7ce6c3', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '07c4229c-36af-4684-b5f2-fd4aa3c88b5d', 'concept'::public.curated_course_node_type, 'Distributional assumptions and when they matter', null, 2),
  ('c3276b70-1f12-45ec-80f6-965e3a1f4465', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '07c4229c-36af-4684-b5f2-fd4aa3c88b5d', 'concept'::public.curated_course_node_type, 'Examples using VO2, strength, reaction time, and injury counts', null, 3),
  ('1f754bdc-0ddc-4b2f-ad4c-052339951fda', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '86057e08-38e8-4c09-bc57-bfb24a792115', 'subtopic'::public.curated_course_node_type, 'Sampling variability and standard error', 'The gist is to understand why samples differ and how that uncertainty is quantified.', 1);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('85e4ee7d-24ad-49b6-b0ea-7f51f5788436', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '1f754bdc-0ddc-4b2f-ad4c-052339951fda', 'concept'::public.curated_course_node_type, 'Sampling distributions and the central limit theorem', null, 0),
  ('c4c6e40d-fdec-4764-9821-637888ce876c', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '1f754bdc-0ddc-4b2f-ad4c-052339951fda', 'concept'::public.curated_course_node_type, 'Standard error of a mean, proportion, and regression estimate', null, 1),
  ('39fff5a4-dd63-49d3-b8a6-1135361d2d82', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '1f754bdc-0ddc-4b2f-ad4c-052339951fda', 'concept'::public.curated_course_node_type, 'Sample size and variability effects', null, 2),
  ('9b970bac-64a8-45d4-9535-6eb603b0c205', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '1f754bdc-0ddc-4b2f-ad4c-052339951fda', 'concept'::public.curated_course_node_type, 'Simulation as a way to see sampling behavior', null, 3),
  ('78b81ffb-c19b-4b3a-ac4b-2e05bb447098', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', null, 'topic'::public.curated_course_node_type, 'Sampling, study design, bias, and measurement error', 'Good statistics cannot rescue weak design. This section helps students see how sampling, design, and measurement quality shape what can be concluded.', 4),
  ('2ed91f6f-910e-45be-b3c3-fee36c233d4f', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '78b81ffb-c19b-4b3a-ac4b-2e05bb447098', 'subtopic'::public.curated_course_node_type, 'Sampling and study design', 'Students learn how design choices determine the strength and limits of evidence.', 0),
  ('92b8f557-6771-4495-9efb-7b82c69df5d1', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '2ed91f6f-910e-45be-b3c3-fee36c233d4f', 'concept'::public.curated_course_node_type, 'Random, convenience, stratified, cluster, and purposive sampling', null, 0),
  ('a2d4591a-b3e9-47d5-8046-4c3e3b8afaf4', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '2ed91f6f-910e-45be-b3c3-fee36c233d4f', 'concept'::public.curated_course_node_type, 'Experimental, quasi-experimental, cohort, case-control, and cross-sectional designs', null, 1),
  ('51674f78-6e73-4411-acb4-1caee20e163d', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '2ed91f6f-910e-45be-b3c3-fee36c233d4f', 'concept'::public.curated_course_node_type, 'Confounding, randomization, blinding, and control groups', null, 2),
  ('8f1302fc-0aea-4c8f-bd2b-8d56b096ce95', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '2ed91f6f-910e-45be-b3c3-fee36c233d4f', 'concept'::public.curated_course_node_type, 'External validity and representation in kinesiology research', null, 3),
  ('b35870bd-5815-41b6-a445-34468296bcb6', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '78b81ffb-c19b-4b3a-ac4b-2e05bb447098', 'subtopic'::public.curated_course_node_type, 'Bias, validity, reliability, and error', 'The point is to distinguish true effects from artifacts of measurement or design.', 1),
  ('c0cd0864-589c-4d8d-857b-4a5bead9305c', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'b35870bd-5815-41b6-a445-34468296bcb6', 'concept'::public.curated_course_node_type, 'Selection bias, information bias, recall bias, and attrition', null, 0),
  ('4484bdf9-8b23-46c7-9dc6-5207e5a5708d', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'b35870bd-5815-41b6-a445-34468296bcb6', 'concept'::public.curated_course_node_type, 'Reliability, validity, standard error of measurement, and minimal detectable change', null, 1),
  ('28b48c85-3194-4d99-96bd-92a6ee421d3b', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'b35870bd-5815-41b6-a445-34468296bcb6', 'concept'::public.curated_course_node_type, 'Inter-rater and intra-rater reliability', null, 2),
  ('1fba28d2-d436-432a-a0f8-1b35c3b5af8e', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'b35870bd-5815-41b6-a445-34468296bcb6', 'concept'::public.curated_course_node_type, 'Instrument calibration and protocol standardization', null, 3),
  ('b6da50ee-e128-47c0-ae0b-fc09dfa200e9', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', null, 'topic'::public.curated_course_node_type, 'Confidence intervals, estimation, effect sizes, and practical significance', 'Estimation often tells a better story than p-values alone. This section teaches students to communicate magnitude, precision, and real-world importance.', 5),
  ('0d5e4908-a87a-4cb3-8c07-5089440232b1', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'b6da50ee-e128-47c0-ae0b-fc09dfa200e9', 'subtopic'::public.curated_course_node_type, 'Confidence intervals and estimation', 'Students learn to report uncertainty around estimates instead of treating sample results as exact.', 0),
  ('8dd2f0b8-bf3d-4fd7-9094-5c83717d7e92', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '0d5e4908-a87a-4cb3-8c07-5089440232b1', 'concept'::public.curated_course_node_type, 'Point estimates and interval estimates', null, 0),
  ('84d24b5a-b459-46f0-a13d-2cfd5f1342ab', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '0d5e4908-a87a-4cb3-8c07-5089440232b1', 'concept'::public.curated_course_node_type, 'Confidence intervals for means, mean differences, proportions, and correlations', null, 1),
  ('02cfd4d3-d517-41ae-8de7-0c3f7d740e9d', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '0d5e4908-a87a-4cb3-8c07-5089440232b1', 'concept'::public.curated_course_node_type, 'Margin of error and sample size effects', null, 2),
  ('7a2c211d-936c-424b-b8d1-9edcb2efbee1', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '0d5e4908-a87a-4cb3-8c07-5089440232b1', 'concept'::public.curated_course_node_type, 'Interpreting intervals without common misconceptions', null, 3),
  ('2591beaa-4667-4c26-9fd2-3fac76a2ccbd', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'b6da50ee-e128-47c0-ae0b-fc09dfa200e9', 'subtopic'::public.curated_course_node_type, 'Effect sizes and meaningful change', 'The gist is to ask not only whether an effect exists, but whether it matters.', 1),
  ('f6b43845-8fee-4935-86b5-a4dd91e95dee', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '2591beaa-4667-4c26-9fd2-3fac76a2ccbd', 'concept'::public.curated_course_node_type, 'Cohen''s d, Hedges'' g, eta-squared, r, odds ratios, and risk ratios', null, 0),
  ('e6a3fa15-746c-484d-841f-1bfaf00f1261', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '2591beaa-4667-4c26-9fd2-3fac76a2ccbd', 'concept'::public.curated_course_node_type, 'Small, medium, large, and context-specific interpretation', null, 1),
  ('b6c94727-25cf-4bbb-b43d-75e567662cef', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '2591beaa-4667-4c26-9fd2-3fac76a2ccbd', 'concept'::public.curated_course_node_type, 'Minimal clinically important difference and smallest worthwhile change', null, 2),
  ('ec24f295-4a76-46d2-8006-5d99ee59a674', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '2591beaa-4667-4c26-9fd2-3fac76a2ccbd', 'concept'::public.curated_course_node_type, 'Practical significance in training, rehab, and health promotion', null, 3),
  ('33e6fbde-218a-4b6e-9a93-2d7f5904d297', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', null, 'topic'::public.curated_course_node_type, 'Hypothesis testing, p-values, power, and multiple comparisons', 'Hypothesis testing is useful but often misunderstood. This section builds correct interpretation and good habits around p-values, errors, power, and overtesting.', 6),
  ('a2b8de20-2bf6-41e8-a27b-fd239bddd8bc', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '33e6fbde-218a-4b6e-9a93-2d7f5904d297', 'subtopic'::public.curated_course_node_type, 'Logic of hypothesis testing', 'Students learn what a hypothesis test can and cannot say.', 0),
  ('01bd5518-d16f-4d3b-be98-e922fdb753f7', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'a2b8de20-2bf6-41e8-a27b-fd239bddd8bc', 'concept'::public.curated_course_node_type, 'Null and alternative hypotheses', null, 0),
  ('7c2d3740-44a5-4c63-b86c-87a9a2a91a3e', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'a2b8de20-2bf6-41e8-a27b-fd239bddd8bc', 'concept'::public.curated_course_node_type, 'Test statistics, p-values, alpha, and decision rules', null, 1),
  ('b3f10470-4711-4f2e-a7d1-f4af5b404f8a', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'a2b8de20-2bf6-41e8-a27b-fd239bddd8bc', 'concept'::public.curated_course_node_type, 'Type I and Type II errors', null, 2),
  ('fb8659f5-198c-4d5b-a0c5-361a3f028f31', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'a2b8de20-2bf6-41e8-a27b-fd239bddd8bc', 'concept'::public.curated_course_node_type, 'One-tailed versus two-tailed tests and preregistered expectations', null, 3),
  ('fb087b78-fb57-42be-b72c-491e2f9e499e', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '33e6fbde-218a-4b6e-9a93-2d7f5904d297', 'subtopic'::public.curated_course_node_type, 'Power, sample size, and multiplicity', 'The point is to understand why studies miss real effects or overstate chance findings.', 1),
  ('b5837c30-77b0-4c31-a4fd-26889711a49e', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'fb087b78-fb57-42be-b72c-491e2f9e499e', 'concept'::public.curated_course_node_type, 'Statistical power and factors that influence it', null, 0),
  ('08d73179-c743-47e0-8352-3ee1b00dd262', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'fb087b78-fb57-42be-b72c-491e2f9e499e', 'concept'::public.curated_course_node_type, 'Effect size, variability, alpha, and sample size logic', null, 1),
  ('fd34730c-e5ed-4d81-8b99-6c1cbc0fac03', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'fb087b78-fb57-42be-b72c-491e2f9e499e', 'concept'::public.curated_course_node_type, 'Multiple comparisons and false discovery risk', null, 2),
  ('b1b4da42-c555-4218-899b-7c2ebc1a860b', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'fb087b78-fb57-42be-b72c-491e2f9e499e', 'concept'::public.curated_course_node_type, 'Replication, transparency, and avoiding p-hacking', null, 3),
  ('d18a06da-cf73-4b70-9aed-4647f4e9731d', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', null, 'topic'::public.curated_course_node_type, 't-tests, nonparametric alternatives, and group comparisons', 'Many kinesiology questions compare two groups or two time points. This section teaches common group-comparison tools and the assumptions behind them.', 7),
  ('a9f88def-9469-4daf-9287-4c4e63f06e84', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'd18a06da-cf73-4b70-9aed-4647f4e9731d', 'subtopic'::public.curated_course_node_type, 't-tests and assumptions', 'Students learn to choose and interpret one-sample, paired, and independent-samples t-tests.', 0),
  ('6d98c02e-4169-4fab-aa5f-d69420e3b2f2', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'a9f88def-9469-4daf-9287-4c4e63f06e84', 'concept'::public.curated_course_node_type, 'One-sample, paired, and independent t-tests', null, 0);
