  ('57c7ff6a-6a62-48d7-8143-3eb4b5289ade', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'a9f88def-9469-4daf-9287-4c4e63f06e84', 'concept'::public.curated_course_node_type, 'Normality, independence, equal variance, and outlier assumptions', null, 1),
