  ('3277b061-78cf-4133-930e-2773db3ebd62', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'd18a06da-cf73-4b70-9aed-4647f4e9731d', 'subtopic'::public.curated_course_node_type, 'Nonparametric and robust alternatives', 'The gist is to know what to do when data do not fit simple parametric assumptions.', 1),
  ('39ab8298-f4c9-4e0e-9bfd-03c00503b5db', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '3277b061-78cf-4133-930e-2773db3ebd62', 'concept'::public.curated_course_node_type, 'Mann-Whitney U and Wilcoxon signed-rank tests', null, 0),
  ('af505f49-561e-4253-88dc-0da4c7edf0e5', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '3277b061-78cf-4133-930e-2773db3ebd62', 'concept'::public.curated_course_node_type, 'Median, rank, and distribution-shift interpretation', null, 1),
  ('f34501a1-00c8-44a9-8ed4-68bb6106f90b', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '3277b061-78cf-4133-930e-2773db3ebd62', 'concept'::public.curated_course_node_type, 'Bootstrap confidence intervals and permutation-test intuition', null, 2),
  ('2a6a6ef5-be3c-4662-90a5-00c826528d78', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '3277b061-78cf-4133-930e-2773db3ebd62', 'concept'::public.curated_course_node_type, 'Reporting limitations and practical meaning', null, 3),
  ('a3063e1c-2b83-449f-a973-0a67040bdd75', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', null, 'topic'::public.curated_course_node_type, 'ANOVA, factorial designs, repeated measures, and post hoc tests', 'ANOVA extends group comparison to more complex designs. This section prepares students for intervention, training, and repeated-measure studies common in kinesiology.', 8),
  ('e473bdb5-e269-4cd1-8238-babbb34a5557', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'a3063e1c-2b83-449f-a973-0a67040bdd75', 'subtopic'::public.curated_course_node_type, 'ANOVA models and design logic', 'Students learn how ANOVA partitions variability and tests group differences.', 0),
  ('dcb5a1dd-5959-4d9d-911a-26c06fb2a7ac', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'e473bdb5-e269-4cd1-8238-babbb34a5557', 'concept'::public.curated_course_node_type, 'One-way ANOVA and omnibus tests', null, 0),
  ('f0afe317-be08-4102-89d9-62fc1c230fe5', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'e473bdb5-e269-4cd1-8238-babbb34a5557', 'concept'::public.curated_course_node_type, 'Factorial designs, main effects, and interactions', null, 1),
  ('05f0bec0-aa20-4018-b1a8-8bc58cff5062', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'e473bdb5-e269-4cd1-8238-babbb34a5557', 'concept'::public.curated_course_node_type, 'Repeated-measures and mixed-design concepts', null, 2),
  ('084d19ca-ee8b-4b92-8b5a-254c70890f58', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'e473bdb5-e269-4cd1-8238-babbb34a5557', 'concept'::public.curated_course_node_type, 'Assumptions: independence, normality, homogeneity, and sphericity', null, 3),
  ('e7792e3f-4ccd-48ae-9dd6-c1a05a316f68', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'a3063e1c-2b83-449f-a973-0a67040bdd75', 'subtopic'::public.curated_course_node_type, 'Post hoc tests and interpretation', 'The point is to move from omnibus significance to clear, responsible conclusions.', 1),
  ('72fffcc0-e21d-4771-99b9-fb661234ffe5', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'e7792e3f-4ccd-48ae-9dd6-c1a05a316f68', 'concept'::public.curated_course_node_type, 'Planned contrasts and post hoc comparisons', null, 0),
  ('05d43683-c78c-45df-9be7-76aea0b511e9', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'e7792e3f-4ccd-48ae-9dd6-c1a05a316f68', 'concept'::public.curated_course_node_type, 'Tukey, Bonferroni, and multiplicity control concepts', null, 1),
  ('d834c378-dd1f-425e-838d-90b480088884', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'e7792e3f-4ccd-48ae-9dd6-c1a05a316f68', 'concept'::public.curated_course_node_type, 'Eta-squared, partial eta-squared, and confidence intervals', null, 2),
  ('3aede4a8-7fa9-43ff-a33d-47129d59b339', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'e7792e3f-4ccd-48ae-9dd6-c1a05a316f68', 'concept'::public.curated_course_node_type, 'Interaction plots and communication of findings', null, 3),
  ('f6f5d8da-cf43-46fb-a365-3d9f9fa4e01c', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', null, 'topic'::public.curated_course_node_type, 'Correlation, regression, prediction, and model interpretation', 'Regression connects variables and supports prediction, but it does not automatically prove causation. This section builds modeling literacy for kinesiology datasets.', 9),
  ('fba7e63c-425e-4e85-8d11-dda527f9135f', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'f6f5d8da-cf43-46fb-a365-3d9f9fa4e01c', 'subtopic'::public.curated_course_node_type, 'Correlation and simple regression', 'Students learn to quantify association and fit simple predictive models.', 0),
  ('84a8927c-05a7-40c3-bb45-cc292a5c6f57', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'fba7e63c-425e-4e85-8d11-dda527f9135f', 'concept'::public.curated_course_node_type, 'Pearson and Spearman correlation', null, 0),
  ('51b80a92-d648-44c1-8c86-d0e5de7143d1', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'fba7e63c-425e-4e85-8d11-dda527f9135f', 'concept'::public.curated_course_node_type, 'Scatterplots, linearity, outliers, and restriction of range', null, 1),
  ('22ac9f3c-6225-4b6a-bde4-6b0a069bc4d9', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'fba7e63c-425e-4e85-8d11-dda527f9135f', 'concept'::public.curated_course_node_type, 'Slope, intercept, R-squared, residuals, and prediction error', null, 2),
  ('f4888f02-7a32-4d6c-ab1c-608c00428836', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'fba7e63c-425e-4e85-8d11-dda527f9135f', 'concept'::public.curated_course_node_type, 'Examples using training load, fitness, strength, gait, and performance', null, 3),
  ('acd5475b-95ec-4abe-b069-9b94b9173445', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'f6f5d8da-cf43-46fb-a365-3d9f9fa4e01c', 'subtopic'::public.curated_course_node_type, 'Multiple regression and model judgment', 'The gist is to interpret models with covariates while watching for overclaiming.', 1),
  ('c931bc28-a487-439c-acc3-1939f0976776', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'acd5475b-95ec-4abe-b069-9b94b9173445', 'concept'::public.curated_course_node_type, 'Confounding, adjustment, and covariate selection', null, 0),
  ('7d3406c1-0c82-468b-9e1a-fdeecb3c4925', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'acd5475b-95ec-4abe-b069-9b94b9173445', 'concept'::public.curated_course_node_type, 'Dummy variables and categorical predictors', null, 1),
  ('9f2f1ae4-58a5-46e2-88dd-35acb5b6ce83', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'acd5475b-95ec-4abe-b069-9b94b9173445', 'concept'::public.curated_course_node_type, 'Multicollinearity, residual diagnostics, and influential cases', null, 2),
  ('e7646088-4530-4ddf-968e-ed3e9ba4be36', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', 'acd5475b-95ec-4abe-b069-9b94b9173445', 'concept'::public.curated_course_node_type, 'Prediction versus explanation and causality cautions', null, 3),
  ('8ee8d941-3afd-4643-a449-cbbfa48d143f', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', null, 'topic'::public.curated_course_node_type, 'Categorical data, epidemiologic measures, and health research interpretation', 'Health and performance research often uses categories: injured/not injured, active/inactive, exposed/unexposed. This section adds tools for categorical outcomes and population health reasoning.', 10),
  ('127f7f77-f45d-48ae-9661-b583948963f9', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '8ee8d941-3afd-4643-a449-cbbfa48d143f', 'subtopic'::public.curated_course_node_type, 'Categorical data analysis', 'Students learn to analyze counts, proportions, and group membership.', 0),
  ('04223be1-2ac1-4133-a339-6e5ac2931ce2', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '127f7f77-f45d-48ae-9661-b583948963f9', 'concept'::public.curated_course_node_type, 'Frequency tables, cross-tabulations, and stacked bar charts', null, 0),
  ('35df83b6-6758-405d-9ea9-acb6d5e9d4ab', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '127f7f77-f45d-48ae-9661-b583948963f9', 'concept'::public.curated_course_node_type, 'Chi-square tests, Fisher''s exact test concepts, and expected counts', null, 1),
  ('6505f264-1a4d-4eea-ab54-fb32071755cc', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '127f7f77-f45d-48ae-9661-b583948963f9', 'concept'::public.curated_course_node_type, 'Risk difference, relative risk, odds ratio, prevalence, and incidence', null, 2),
  ('612c8bd2-4dd7-420a-97b3-4dcf02d353d2', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '127f7f77-f45d-48ae-9661-b583948963f9', 'concept'::public.curated_course_node_type, 'Interpreting categorical outcomes in health and sport settings', null, 3),
  ('3ef1dcce-09ab-44ba-91c4-43a9ee85b886', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '8ee8d941-3afd-4643-a449-cbbfa48d143f', 'subtopic'::public.curated_course_node_type, 'Evidence appraisal and research interpretation', 'The point is to read statistical claims in articles with healthy skepticism.', 1),
  ('57732a19-6272-412f-b02e-6455452bf4f1', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '3ef1dcce-09ab-44ba-91c4-43a9ee85b886', 'concept'::public.curated_course_node_type, 'Clinical versus statistical significance', null, 0),
  ('2348bd8b-58dd-4280-9948-c5fd786079c5', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '3ef1dcce-09ab-44ba-91c4-43a9ee85b886', 'concept'::public.curated_course_node_type, 'Confidence intervals, effect sizes, and external validity in articles', null, 1),
  ('727abb6d-7af7-4f6c-b874-c2386fa6391a', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '3ef1dcce-09ab-44ba-91c4-43a9ee85b886', 'concept'::public.curated_course_node_type, 'Common misinterpretations in abstracts and media reports', null, 2);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('45c6125e-a8c7-4cc2-b60b-2110f8ef5781', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '3ef1dcce-09ab-44ba-91c4-43a9ee85b886', 'concept'::public.curated_course_node_type, 'CONSORT/STROBE-style reporting awareness', null, 3),
