  ('4df16149-55b1-4b2a-93c5-ab3ef2cb2ccf', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '40fabb41-fefc-40d1-b356-d97f3bea955e', 'subtopic'::public.curated_course_node_type, 'Software workflows and reproducibility', 'Students learn practical habits that make analyses checkable and reusable.', 0),
  ('941baf51-70d9-4ca6-8839-2399c04b9c5a', 'c5e8a1d4-7b29-4f06-9a31-6d0c3e8b5f17', '4df16149-55b1-4b2a-93c5-ab3ef2cb2ccf', 'concept'::public.curated_course_node_type, 'Spreadsheet hygiene, codebooks, data dictionaries, and versioning', null, 0),
